import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs['target_snapshot'].copy()
    cdc_events = inputs['cdc_events'].copy()
    watermark = inputs['watermark'].copy()

    # Determine high watermark timestamp (events with event_ts <= high_ts already applied)
    high_ts = None
    if len(watermark) > 0 and 'high_ts' in watermark.columns:
        high_ts = watermark['high_ts'].iloc[0]

    events = cdc_events.copy()
    if high_ts is not None:
        events = events[events['event_ts'] > high_ts]

    # Sequential application requires strict per-item ordering by (event_ts, event_seq)
    events = events.sort_values(
        by=['item_id', 'event_ts', 'event_seq'],
        kind='mergesort'
    )

    # Build initial state from the existing snapshot
    state = {}
    for _, row in target_snapshot.iterrows():
        item = row['item_id']
        state[item] = {
            'qty_on_hand': row['qty_on_hand'],
            'last_event_ts': row['last_event_ts'],
            'present': True,
        }

    # Apply each event sequentially, per item, in (event_ts, event_seq) order
    for _, ev in events.iterrows():
        item = ev['item_id']
        op = ev['op']
        qty = ev['qty']
        ts = ev['event_ts']

        if item not in state:
            state[item] = {
                'qty_on_hand': 0,
                'last_event_ts': None,
                'present': False,
            }

        s = state[item]

        if op == 'D':
            # Delete: remove item from snapshot (reset qty, mark absent)
            s['present'] = False
            s['qty_on_hand'] = 0
            s['last_event_ts'] = ts

        elif op == 'R':
            # Receipt: accumulate; if item was absent/deleted, re-create starting from 0
            if not s['present']:
                s['qty_on_hand'] = 0
            s['qty_on_hand'] = s['qty_on_hand'] + qty
            s['present'] = True
            s['last_event_ts'] = ts

        elif op == 'A':
            # Adjustment: absolute reset; re-creates item if absent/deleted
            s['qty_on_hand'] = qty
            s['present'] = True
            s['last_event_ts'] = ts

        # unknown ops are ignored (not part of the legacy spec)

    rows = []
    for item, s in state.items():
        if s['present']:
            rows.append({
                'item_id': item,
                'qty_on_hand': s['qty_on_hand'],
                'last_event_ts': s['last_event_ts'],
            })

    new_snapshot = pd.DataFrame(
        rows, columns=['item_id', 'qty_on_hand', 'last_event_ts']
    )

    return {'new_snapshot': new_snapshot}
